-- ========================================================================

-- Computed grading result for a nerve conduction study request (four-axis engine).

CREATE TABLE nerve_conduction_study_test_request_grade (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    nerve_conduction_study_test_request_id UUID NOT NULL UNIQUE
        REFERENCES nerve_conduction_study_test_request(id) ON DELETE CASCADE,

    -- Axis A: appropriateness (AANEM / AAN electrodiagnostic guidelines, 1-9 scale)
    appropriateness_score INTEGER
        CHECK (appropriateness_score IS NULL OR appropriateness_score BETWEEN 1 AND 9),
    appropriateness_band VARCHAR(25) NOT NULL DEFAULT ''
        CHECK (appropriateness_band IN ('usually-appropriate', 'may-be-appropriate', 'usually-not-appropriate', '')),

    -- Axis B: procedural risk (needle EMG vs anticoagulant / pacemaker)
    procedural_risk_band VARCHAR(15) NOT NULL DEFAULT ''
        CHECK (procedural_risk_band IN ('low', 'moderate', 'high', '')),

    -- Axis C: request completeness
    completeness_percent INTEGER
        CHECK (completeness_percent IS NULL OR completeness_percent BETWEEN 0 AND 100),

    -- Axis D: triage priority
    triage_tier VARCHAR(15) NOT NULL DEFAULT ''
        CHECK (triage_tier IN ('routine', 'urgent', '')),
    target_timeframe VARCHAR(50) NOT NULL DEFAULT '',

    recommendation VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (recommendation IN ('accept', 'query-referrer', 'redirect', 'reject', '')),
    clinician_notes TEXT NOT NULL DEFAULT '',
    signed_at TIMESTAMPTZ,
    graded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TRIGGER trigger_nerve_conduction_study_test_request_grade_updated_at
    BEFORE UPDATE ON nerve_conduction_study_test_request_grade
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE nerve_conduction_study_test_request_grade IS
    'Computed four-axis grading result: appropriateness (AANEM / AAN 1-9), procedural risk, request completeness, and triage priority.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.nerve_conduction_study_test_request_id IS
    'Foreign key to the parent request (unique, 1:1).';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.appropriateness_score IS
    'AANEM / AAN electrodiagnostic appropriateness score (1-9), based on indication match.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.appropriateness_band IS
    'Appropriateness band: usually-appropriate (7-9), may-be-appropriate (4-6), usually-not-appropriate (1-3).';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.procedural_risk_band IS
    'Procedural risk band: low, moderate, high. Driven by needle EMG against anticoagulation or a cardiac device.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.completeness_percent IS
    'Request completeness as a percentage of mandatory fields (0-100).';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.triage_tier IS
    'Assigned triage tier: routine, urgent.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.target_timeframe IS
    'Target timeframe for the study implied by the triage tier.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.recommendation IS
    'Vetting recommendation: accept, query-referrer, redirect, reject.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.clinician_notes IS
    'Free-text vetting notes.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.signed_at IS
    'Timestamp of vetting clinician electronic signature.';
COMMENT ON COLUMN nerve_conduction_study_test_request_grade.graded_at IS
